('ai-automation-nocode', 'No-Code AI Automation & Workflow Design', 'ACAD-202', '6 Weeks', '5-6 hrs / week', 'Project Labs + Step-by-Step Builds', 'Intermediate', '$550', 'Connect apps and AI to build automated bots, lead processors, and smart databases without coding.', '#10B981', 'Build autonomous workflows that parse emails, enrich data, draft replies, and update spreadsheets.', 'Make.com, Zapier Central, Airtable AI, OpenAI API, Slack', 'Automated customer onboarding and lead qualification assistant on Make.com and Airtable.'),
('prompt-engineering', 'Applied Prompt Engineering & Creative AI', 'ACAD-303', '5 Weeks', '5 hrs / week', 'Creative Sprints & Peer Reviews', 'Beginner to Intermediate', '$480', 'Master structured instructions, few-shot prompting, and generative visual storytelling.', '#F59E0B', 'Construct robust prompt chains for marketing campaigns, educational content, and visual design.', 'Claude Projects, Midjourney v6, OpenAI Playground, Runway Gen-3', 'Comprehensive brand launch package with visual identity, copy deck, and video concepts.'),
('practical-web-ai', 'Building Real-World AI Web Applications', 'ACAD-404', '8 Weeks', '6-8 hrs / week', 'Code Labs + Weekly Mentorship', 'Intermediate', '$650', 'Build and deploy working, interactive AI apps with modern React frontends and cloud backends.', '#6366F1', 'For students and junior developers who want to ship real web applications powered by generative AI.', 'React.js, Next.js, OpenAI API, CSS, Supabase, Vercel', 'Live publicly deployed AI web application with streaming chat and document upload.'),
('ai-business-ops', 'AI for Modern Business & Marketing Operations', 'ACAD-505', '4 Weeks', '4 hrs / week', 'Case Studies & Live Strategy', 'Beginner to Intermediate', '$420', 'Use AI to conduct deep competitive research, automate campaign assets, and scale marketing.', '#EC4899', 'For marketing students, business analysts, and startup operators to accelerate research and content.', 'Claude 3.5, HubSpot AI, Canva Magic Studio, Clay.com, Gemini', 'Full AI Marketing Strategy & Operations Playbook for a growth-stage company.');

